import json, re
from transformers import AutoTokenizer
tok=AutoTokenizer.from_pretrained("/workspace/models/Qwen2.5-0.5B-Instruct")

boxed_re=re.compile(r"\\boxed\{([^{}]*)\}")
num_re=re.compile(r"-?\d[\d,]*(?:\.\d+)?")

def norm(x):
    if x is None: return None
    return str(x).replace(",","").rstrip(".")

def last_num(s):
    last=None
    for m in num_re.finditer(s or ""):
        last=norm(m.group(0))
    return last

def boxed_num(s):
    ms=list(boxed_re.finditer(s or ""))
    if not ms: return None
    return last_num(ms[-1].group(1))

def load(p):
    return [json.loads(l) for l in open(p)]

def toklen(s):
    return len(tok(s, add_special_tokens=False)["input_ids"])

for path in [
