]:
    rows=load(path)
    lens=[toklen(r["output"]) for r in rows]
    n=len(rows)
    lens_s=sorted(lens)
    def subset(pred):
        idxs=[i for i,L in enumerate(lens) if pred(L)]
        return idxs
    def mean_score(idxs):
        if not idxs: return float("nan")
        return sum(rows[i]["score"] for i in idxs)/len(idxs)
    def mean_box(idxs):
        if not idxs: return float("nan")
        return sum(1 for i in idxs if boxed_num(rows[i]["output"])==norm(rows[i]["gts"]))/len(idxs)
