    print(f"  reward short<200 {mean_score(short):.3f} n={len(short)} mid {mean_score(mid):.3f} n={len(mid)} trunc {mean_score(t500):.3f} n={len(t500)}")
    print(f"  boxed  short {mean_box(short):.3f} mid {mean_box(mid):.3f} trunc {mean_box(t500):.3f}")

print("\nprompt lens")
for path,k in [("/workspace/results/run60/val_generations/0.jsonl",1319),("/workspace/results/run60/rollouts/1.jsonl",512)]:
