import json, re
from collections import Counter
from transformers import AutoTokenizer
tok=AutoTokenizer.from_pretrained("/workspace/models/Qwen2.5-0.5B-Instruct")

def load(p):
    return [json.loads(l) for l in open(p)]

base=load("/workspace/results/run60/val_generations/0.jsonl")
fin=load("/workspace/results/run60/val_generations/60.jsonl")

def tlen(s):
    return len(tok(s, add_special_tokens=False)["input_ids"])

# truncation related flips
gain_from_untrunc=0
loss_to_trunc=0
gain_other=0
loss_other=0
both_trunc_staywrong=0
# also length buckets of base for lost vs gained
for a,b in zip(base, fin):
    la, lb = tlen(a["output"]), tlen(b["output"])
    ca, cb = a["score"]==1, b["score"]==1
    a_tr, b_tr = la>=500, lb>=500
    if (not ca) and cb:
        if a_tr and not b_tr:
            gain_from_untrunc += 1
        else:
            gain_other += 1
    elif ca and (not cb):
        if (not a_tr) and b_tr:
            loss_to_trunc += 1
        else:
            loss_other += 1
print("gains from leaving truncation", gain_from_untrunc, "other gains", gain_other)
print("losses into truncation", loss_to_trunc, "other losses", loss_other)

# base trunc count and their fate
base_tr=0
base_tr_fixed=0
base_ok_became_tr=0
base_ok=0
for a,b in zip(base, fin):
    la, lb = tlen(a["output"]), tlen(b["output"])
    if la>=500:
        base_tr+=1
        if b["score"]==1 and lb<500:
            base_tr_fixed+=1
    if a["score"]==1 and lb>=500 and la<500:
        base_ok_became_tr+=1
    if a["score"]==1:
        base_ok+=1
print(f"base trunc {base_tr}, of which now correct and untrunc {base_tr_fixed}")
print(f"base correct that became trunc {base_ok_became_tr} of {base_ok}")

# final trunc score already known ~0.03
# contribution: if we only count non-truncated items
def acc_nontrunc(rows):
    keep=[]
    for r in rows:
        if tlen(r["output"])<500:
            keep.append(r["score"])
    return sum(keep)/len(keep), len(keep)
print("nontrunc acc base", acc_nontrunc(base))
print("nontrunc acc 60", acc_nontrunc(fin))

# step 40 too? optional skip
print("logged base", sum(r['score'] for r in base)/len(base), "final", sum(r['score'] for r in fin)/len(fin))
